def delimiters_ok(text):
 pairs = {")": "(", "]": "[", "}": "{"}
 stack = []
 for ch in text:
 if ch in "([{":
 stack.append(ch)
 elif ch in ")]}":
 if not stack or stack[-1] != pairs[ch]:
 return False
 stack.pop()
 return not stack

