def max_window_sum(values, k):
 if k <= 0 or k > len(values):
 raise ValueError("invalid window")
 current = sum(values[:k])
 best = current
 for i in range(k, len(values)):
 current += values[i] - values[i - k]
 if current > best:
 best = current
 return best

