def group_in_order(items, key_fn):
 order = []
 buckets = {}
 for item in items:
 key = key_fn(item)
 if key not in buckets:
 buckets[key] = []
 order.append(key)
 buckets[key].append(item)
 return [(key, buckets[key]) for key in order]

