def merge_ranges(ranges):
 if not ranges:
 return []
 ordered = sorted(ranges, key=lambda r: r[0])
 out = [list(ordered[0])]
 for start, end in ordered[1:]:
 if start <= out[-1][1]:
 out[-1][1] = max(out[-1][1], end)
 else:
 out.append([start, end])
 return out

