import heapq

def shortest_cost(graph, start, goal):
 best = {start: 0}
 heap = [(0, start)]
 while heap:
 cost, node = heapq.heappop(heap)
 if cost != best.get(node, None):
 continue
 if node == goal:
 return cost
 for nxt, weight in graph.get(node, []):
 cand = cost + weight
 if cand < best.get(nxt, float("inf")):
 best[nxt] = cand
 heapq.heappush(heap, (cand, nxt))
 return None

