def is_safe(available, allocation, need):
 work = list(available)
 finish = [False] * len(allocation)
 while True:
 progressed = False
 for i, done in enumerate(finish):
 if done:
 continue
 if all(need[i][j] <= work[j] for j in range(len(work))):
