class TokenBucket:
 def __init__(self, rate, burst):
 self.rate = rate
 self.burst = burst
 self.tokens = float(burst)
 self.t = 0.0

 def allow(self, time, cost=1):
 if time < self.t:
 raise ValueError("time")
