def eval_rpn(tokens):
 stack = []
 ops = {
 "+": lambda a, b: a + b,
 "-": lambda a, b: a - b,
 "*": lambda a, b: a * b,
 "/": lambda a, b: a // b,
 }
 for tok in tokens:
 if tok in ops:
 b = stack.pop()
 a = stack.pop()
 stack.append(ops[tok](a, b))
 else:
 stack.append(int(tok))
 if len(stack) != 1:
 raise ValueError("rpn")
 return stack[0]

