def within_edit(a, b, k):
 if abs(len(a) - len(b)) > k:
 return False
 prev = list(range(len(b) + 1))
 for i, ca in enumerate(a, start=1):
 row = [i]
 for j, cb in enumerate(b, start=1):
 cost = 0 if ca == cb else 1
 row.append(min(row[j - 1] + 1, prev[j] + 1, prev[j - 1] + cost))
 prev = row
 return prev[-1] <= k

