def parse_flags(argv):
 flags = {}
 args = []
 i = 0
 while i < len(argv):
 tok = argv[i]
 if tok == "--verbose":
 flags["verbose"] = True
 i += 1
 elif tok.startswith("--"):
 name = tok[2:]
 if i + 1 >= len(argv):
 raise ValueError("missing")
 flags[name] = argv[i + 1]
 i += 2
 else:
 args.append(tok)
 i += 1
 return {"flags": flags, "args": args}

