class Ring:
 def __init__(self, n):
 if n < 1:
 raise ValueError("n")
 self.buf = [None] * n
 self.n = n
 self.i = 0
 self.size = 0

 def push(self, x):
 self.buf[self.i] = x
 self.i = (self.i + 1) % self.n
 self.size = min(self.size + 1, self.n)

 def snapshot(self):
 start = (self.i - self.size) % self.n
 return [self.buf[(start + k) % self.n] for k in range(self.size)]

