class UnionFind:
 def __init__(self, n):
 self.p = list(range(n))
 self.r = [0] * n

 def find(self, i):
 while self.p[i] != i:
 self.p[i] = self.p[self.p[i]]
 i = self.p[i]
 return i

 def union(self, i, j):
 a, b = self.find(i), self.find(j)
 if a == b:
 return False
 if self.r[a] < self.r[b]:
 a, b = b, a
 self.p[b] = a
 if self.r[a] == self.r[b]:
 self.r[a] += 1
 return True

