from collections import deque

def bfs_order(graph, start):
 seen = {start}
 q = deque([start])
 order = []
 while q:
 node = q.popleft()
 order.append(node)
 for nxt in graph.get(node, []):
 if nxt not in seen:
 seen.add(nxt)
 q.append(nxt)
 return order

