def lev_one(a,b):
    if abs(len(a)-len(b))>1: return False
    if len(a)==len(b):
        return sum(x!=y for x,y in zip(a,b))<=1
    if len(a)>len(b): a,b=b,a
    i=j=diff=0
    while i<len(a) and j<len(b):
        if a[i]==b[j]:
            i+=1; j+=1
        else:
            diff+=1; j+=1
