from collections import deque

def hops(graph, start, goal):
 if start == goal:
 return 0
 seen = {start}
 q = deque([(start, 0)])
 while q:
 node, dist = q.popleft()
 for nxt in graph.get(node, []):
 if nxt in seen:
 continue
 if nxt == goal:
 return dist + 1
 seen.add(nxt)
 q.append((nxt, dist + 1))
 return -1

