def components(n, edges):
 parent = list(range(n))

 def find(x):
 while parent[x] != x:
 parent[x] = parent[parent[x]]
 x = parent[x]
 return x

 def union(a, b):
 ra, rb = find(a), find(b)
 if ra != rb:
 parent[rb] = ra

 for a, b in edges:
 union(a, b)
 return len({find(i) for i in range(n)})

