def isbn10_ok(code):
 compact = code.replace("-", "")
 if len(compact) != 10:
 return False
 total = 0
 for i, ch in enumerate(compact):
 if i < 9:
 if not ch.isdigit():
 return False
 total += int(ch) * (10 - i)
