 compact = code.replace("-", "")
 if len(compact) != 10:
 return False
 total = 0
 for i, ch in enumerate(compact):
 if i < 9:
 if not ch.isdigit():
 return False
 total += int(ch) * (10 - i)
 else:
 if ch in "Xx":
 total += 10
 elif ch.isdigit():
 total += int(ch)
 else:
 return False
 return total % 11 == 0

