def join_query(base, extra):
 if "?" in base:
 path, qs = base.split("?", 1)
 pairs = {}
 if qs:
 for part in qs.split("&"):
 if not part:
 continue
 if "=" in part:
 k, v = part.split("=", 1)
 pairs[k] = v
 else:
 pairs[part] = ""
 else:
 pairs = {}
 else:
 path, pairs = base, {}
 pairs.update(extra)
 if not pairs:
 return path
 joined = "&".join(f"{k}={v}" for k, v in pairs.items())
 return path + "?" + joined

