def merge_headers(*maps):
 order = []
 lower = {}
 for mapping in maps:
 for key, value in mapping.items():
 lk = key.lower()
 if lk in lower:
 order.remove(lower[lk][0])
 lower[lk] = (key, value)
 order.append(key)
 return {k: lower[k.lower()][1] for k in order}

