function deepGet(obj, path) {
 if (!path) return obj;
 const parts = path.split('.');
 let cur = obj;
 for (const p of parts) {
 if (cur == null || typeof cur !== 'object') return undefined;
 cur = cur[p];
 }
 return cur;
}
module.exports = { deepGet };

