function parseQuery(q) {
 if (!q) return {};
 const out = {};
 for (const part of q.split('&')) {
 if (!part) continue;
 const i = part.indexOf('=');
 if (i < 0) out[part] = '';
 else out[part.slice(0, i)] = part.slice(i + 1);
 }
 return out;
}
module.exports = { parseQuery };

